1	#!/usr/bin/env node
2	// Fábrica: un comando por spec.
3	//   node factory/cli.mjs run specs/spec-1-reconocimiento.md      pipeline completo -> rama + PR (sin merge)
4	//   node factory/cli.mjs suite                                   suite completa funcional + visual + honestidad
5	//   node factory/cli.mjs honestidad                              solo el control de verificación honesta
6	//   node factory/cli.mjs aprobar-linea-base <png|--pendientes> --razon "..."   (HUMANO)
7	//   node factory/cli.mjs aprobar-pruebas --razon "..."                          (HUMANO)
8	import fs from 'node:fs';
9	import path from 'node:path';
10	import { RAIZ, Corrida, sh, shOk, escribir, leer, existe, archivos } from './lib/util.mjs';
11	import { llamarIA, extraerJSON } from './lib/ia.mjs';
12	import * as moodle from './lib/moodle.mjs';
13	import { correrPruebas, resumen, contextoFallos, copiasDeHelpers } from './lib/pruebas.mjs';
14	import { auditar } from './lib/auditor.mjs';
15	import { generarTrazabilidad } from './lib/trazabilidad.mjs';
16	import { lineasBaseNuevas, registrarPendientes, proponerLineasBase, aprobarLineaBase } from './lib/lineas-base.mjs';
17	
18	const MAX_REINTENTOS = Number(process.env.FACTORY_REINTENTOS || 3);
19	const [, , comando, ...resto] = process.argv;
20	const opt = (n) => { const i = resto.indexOf(n); return i >= 0 ? resto[i + 1] : null; };
21	const ETAPAS_RUN = ['precondicion', 'analisis', 'sondas', 'implementacion', 'pruebas', 'mutacion', 'regresion', 'alcance', 'honestidad', 'pr'];
22	// Reglas del auditor que se ven sin ejecutar nada: mejor corregirlas antes de gastar una corrida de pruebas.
23	const REGLAS_ESTATICAS = new Set(['SIN-ASSERTS', 'ASSERT-TRIVIAL', 'ASSERT-SIN-AWAIT', 'ERROR-TRAGADO', 'RED-SIMULADA', 'TEST-ONLY', 'OMISION-NUEVA', 'OMITIDA']);
24	const ETAPAS_SUITE = ['precondicion', 'pruebas', 'honestidad'];
25	let corridaActiva = null;
26	
27	const comandos = { run, suite, honestidad, 'aprobar-linea-base': aprobarLB, 'aprobar-pruebas': aprobarPruebas };
28	if (!comandos[comando]) { console.error(`Uso: node factory/cli.mjs <${Object.keys(comandos).join('|')}> ...`); process.exit(2); }
29	try { process.exitCode = await comandos[comando](); } catch (e) {
30	  // Una excepción no debe dejar estado.json diciendo que la etapa sigue en curso.
31	  const enCurso = corridaActiva?.etapaEnCurso();
32	  if (e.limiteIA) {
33	    if (enCurso) corridaActiva.etapa(enCurso, 'BLOQUEADO', `Límite de uso de la IA: ${e.message}`);
34	    console.error(`\n⛔ ${e.message}\nLa corrida quedó en su rama. Cuando la IA vuelva a estar disponible:\n  node factory/cli.mjs run <spec> --reanudar $(git branch --show-current)`);
35	    process.exitCode = 3;
36	  } else {
37	    if (enCurso) corridaActiva.etapa(enCurso, 'FALLIDO', String(e.message || e).slice(0, 500));
38	    console.error(e.stack || e); process.exitCode = 1;
39	  }
40	}
41	
42	// ---------------------------------------------------------------------------------------------------------
43	async function run() {
44	  const specPath = resto.find((a) => !a.startsWith('--'));
45	  if (!specPath || !existe(specPath)) throw new Error(`Spec no encontrado: ${specPath}`);
46	  const specTxt = leer(specPath);
47	  const specId = (specTxt.match(/^id:\s*(\S+)/m) || [])[1] || path.basename(specPath, '.md');
48	  const specDir = `salidas/${specId}`;
49	  const c = corridaActiva = new Corrida(specId);
50	  // --reanudar <rama>: retoma una corrida interrumpida (p. ej. por límite de uso de la IA) reutilizando el plan
51	  // y el código ya generados en esa rama; vuelve a ejecutar TODAS las verificaciones desde la etapa 4.
52	  const reanudar = opt('--reanudar');
53	  const rama = reanudar || `factory/${specId}-${c.id.slice(0, 15)}`;
54	  c.iniciarEstado(ETAPAS_RUN, { spec: specPath, rama, reanudada: Boolean(reanudar) });
55	  c.log('inicio', `Spec ${specPath} (${specId}). Corrida ${c.dir}. Rama ${rama}${reanudar ? ' (REANUDADA)' : ''}.`);
56	
57	  // 0. Precondiciones
58	  if (!moodle.moodleArriba()) return falla(c, 'precondicion', 'Moodle no responde en http://localhost:8090. Ejecutar: bash entorno/setup.sh');
59	  // La carpeta de esta misma corrida ya existe (es donde se escribe el log): no cuenta como cambio.
60	  const sucio = sh('git status --porcelain').out.split('\n').filter((l) => l && !l.slice(3).startsWith('corridas/')).join('\n');
61	  if (sucio) return falla(c, 'precondicion', 'El árbol de trabajo tiene cambios sin commit. La fábrica parte de un estado limpio.', sucio);
62	  if (reanudar) {
63	    shOk(`git checkout -q ${reanudar}`);
64	    // La fábrica de main (con sus correcciones) es la que verifica; la rama solo aporta plan, código y pruebas.
65	    shOk('git checkout -q main -- factory entorno playwright.config.ts package.json');
66	    if (!existe(`${specDir}/plan.json`)) return falla(c, 'reanudar', `La rama ${reanudar} no tiene ${specDir}/plan.json.`);
67	  } else {
68	    shOk(`git checkout -q -b ${rama}`);
69	    fs.rmSync(path.join(RAIZ, specDir), { recursive: true, force: true });
70	    escribir(`${specDir}/spec.md`, specTxt);
71	  }
72	  c.etapa('precondicion', 'VALIDADO', 'Moodle responde y el árbol de trabajo está limpio.');
73	
74	  // 1. Análisis: plan, capa, bordes, criterios -> pruebas
75	  let plan = reanudar ? validarPlan(JSON.parse(leer(`${specDir}/plan.json`)), specId) : null;
76	  if (reanudar) c.log('reanudar', `Se reutiliza ${specDir}/plan.json y el código/pruebas de la rama. Análisis e implementación no se repiten.`);
77	  let feedback = '';
78	  for (let i = 1; i <= 3 && !plan; i++) {
79	    const lineas_base = fs.readdirSync(path.join(RAIZ, 'visual/lineas-base')).filter((f) => f.endsWith('.png')).join(', ') || '(ninguna todavía)';
80	    const r = llamarIA(c, { rol: 'analista', plantilla: 'analista', vars: { spec: specTxt, spec_id: specId, conocimiento: leer('factory/conocimiento/moodle-5.3.md'), helpers: leer('factory/regresion/helpers.ts'), feedback, lineas_base } });
81	    try {
82	      plan = validarPlan(extraerJSON(r.texto), specId);
83	      c.log('analisis', `Plan válido en intento ${i}: capa ${plan.componente || '(solo pruebas)'} — ${plan.criterios.length} criterios, ${plan.bordes.length} bordes.`);
84	    } catch (e) {
85	      feedback = `Tu respuesta anterior no es un plan válido: ${e.message}. Devolvé SOLO el bloque \`\`\`json con el esquema pedido.`;
86	      c.log('analisis', `Plan inválido (intento ${i}), se reintenta.`, e.message);
87	    }
88	  }
89	  if (!plan) return falla(c, 'analisis', 'La IA no produjo un plan válido en 3 intentos.');
90	  escribir(`${specDir}/plan.json`, JSON.stringify(plan, null, 2));
91	  // Una ambigüedad que solo producto puede resolver detiene la corrida antes de gastar en construir.
92	  const bloqueantes = plan.bordes.filter((b) => b.bloqueante === true);
93	  if (bloqueantes.length) return bloquear(c, rama, specDir, specPath, bloqueantes);
94	  c.etapa('analisis', 'VALIDADO', `${reanudar ? 'Plan reutilizado de la rama' : 'Plan válido'}: ${plan.criterios.length} criterios, ${plan.bordes.length} bordes.`);
95	
96	  // 2. Sondas: verificar contra la realidad antes de construir (contratos externos, comportamiento actual)
97	  const sondas = ejecutarSondas(c, plan.sondas || []);
98	  escribir(`${specDir}/sondas.json`, JSON.stringify(sondas, null, 2));
99	  c.etapa('sondas', 'EJECUTADO', `${sondas.length} sonda(s).`);
100	
101	  // 3. Implementación (código + pruebas)
102	  const varsImpl = { spec: specTxt, spec_id: specId, plan, sondas, conocimiento: leer('factory/conocimiento/moodle-5.3.md'), helpers: leer('factory/regresion/helpers.ts'), spec_dir: specDir };
103	  if (!reanudar) llamarIA(c, { rol: 'implementador', plantilla: 'implementador', vars: varsImpl, escritura: specDir });
104	  c.etapa('implementacion', 'EJECUTADO', reanudar ? 'Código y pruebas reutilizados de la rama.' : 'Código y pruebas generados.');
105	
106	  // 4. Bucle validar -> desplegar -> probar -> corregir
107	  let verde = false;
108	  let res = null;
109	  for (let intento = 1; intento <= MAX_REINTENTOS + 1; intento++) {
110	    const problemas = validacionesEstaticas(c, specDir, plan);
111	    let detalle = problemas.join('\n');
112	    if (!problemas.length) {
113	      const d = moodle.desplegar(specDir);
114	      c.log('despliegue', `Plugins: ${d.plugins.map((p) => p.componente).join(', ') || '(ninguno)'} — upgrade ${d.ok ? 'OK' : 'FALLÓ'}`, d.ok ? null : d.salida);
115	      if (!d.ok) detalle = `La actualización de Moodle falló:\n${d.salida}`;
116	      else {
117	        moodle.reset();
118	        const pruebasSpec = archivos(`${specDir}/pruebas`, (f) => f.endsWith('.spec.ts'));
119	        res = correrPruebas(pruebasSpec, c.ruta('spec'), { crearLineasBaseFaltantes: true });
120	        const s = resumen(res.resultados);
121	        c.log('pruebas', `Intento ${intento}: ${s.passed} OK, ${s.failed} fallidas, ${s.skipped} omitidas.`, s.failed ? contextoFallos(c.ruta('spec'), res.resultados) : null);
122	        if (s.failed === 0 && s.passed > 0) { verde = true; break; }
123	        detalle = s.passed + s.failed === 0 ? `No se ejecutó ninguna prueba.\n${res.salida.slice(-3000)}` : contextoFallos(c.ruta('spec'), res.resultados);
124	      }
125	    }
126	    if (intento > MAX_REINTENTOS) break;
127	    c.log('reintento', `Intento ${intento} no quedó verde. Se le pide a la IA que corrija (${intento}/${MAX_REINTENTOS}).`);
128	    llamarIA(c, { rol: 'corrector', plantilla: 'corrector', vars: { ...varsImpl, problemas: detalle, intento: String(intento) }, escritura: specDir });
129	  }
130	  if (!verde) return falla(c, 'pruebas', `Las pruebas del spec no quedaron en verde tras ${MAX_REINTENTOS} reintentos. Se detiene sin PR; la rama ${rama} queda para diagnóstico.`);
131	  c.etapa('pruebas', 'VALIDADO', 'Pruebas del spec en verde.');
132	
133	  // 5. Mutación "sin la funcionalidad": las pruebas @requiere-feature deben fallar sin el plugin
134	  let sinFeature = null;
135	  const probarSinFuncionalidad = () => {
136	    if (!moodle.pluginsDe(specDir).length) { c.etapa('mutacion', 'EJECUTADO', 'No aplica: el spec no trae plugin.'); return; }
137	    const r = moodle.retirar(specDir);
138	    c.log('mutacion', `Plugin retirado para probar que las pruebas detectan su ausencia (${r.ok ? 'OK' : 'con avisos'}).`);
139	    moodle.reset();
140	    const pruebasSpec = archivos(`${specDir}/pruebas`, (f) => f.endsWith('.spec.ts'));
141	    sinFeature = correrPruebas(pruebasSpec, c.ruta('sin-feature'), { grep: '@requiere-feature' }).resultados;
142	    const s = resumen(sinFeature);
143	    c.log('mutacion', `Sin la funcionalidad: ${s.failed} fallan (esperado), ${s.passed} pasan (cada una es un hallazgo).`);
144	    moodle.desplegar(specDir);
145	    c.etapa('mutacion', s.passed ? 'EJECUTADO' : 'VALIDADO', `Sin la funcionalidad: ${s.failed} fallan, ${s.passed} pasan.`);
146	  };
147	  probarSinFuncionalidad();
148	
149	  // 6. Regresión completa (nada de lo existente se rompió) + líneas base nuevas
150	  moodle.reset();
151	  let total = correrPruebas([], c.dir, { crearLineasBaseFaltantes: false });
152	  // Pantallas que el spec declara cambiar A PROPÓSITO: la imagen obtenida se PROPONE como nueva línea base,
153	  // pendiente de aprobación humana en el PR. Diferencias en pantallas NO declaradas siguen siendo fallos.
154	  const propuestas = proponerCambiosVisuales(c, plan, total.resultados);
155	  if (propuestas.length) {
156	    c.log('visual', `Cambios visuales declarados por el plan (${plan.pantallas_afectadas.join(', ')}): se proponen ${propuestas.length} líneas base, pendientes de aprobación humana.`, propuestas.join('\n'));
157	    copiarDiferencias(c);
158	    moodle.reset();
159	    total = correrPruebas([], c.dir, { crearLineasBaseFaltantes: false });
160	  }
161	  // Una prueba del propio spec que pasó sola y falla en la suite es inestable: va al corrector igual que en la etapa 4.
162	  // Los fallos de pruebas de otros specs no se corrigen aquí: son regresiones y detienen la corrida.
163	  for (let i = 1; i <= MAX_REINTENTOS; i++) {
164	    const propias = total.resultados.filter((r) => ['failed', 'timedOut', 'interrupted'].includes(r.estado) && (r.archivo || '').includes(specDir));
165	    if (!propias.length) break;
166	    c.log('reintento', `${propias.length} prueba(s) del spec fallaron en la suite completa. Se le pide a la IA que corrija (${i}/${MAX_REINTENTOS}).`);
167	    const problemas = `Estas pruebas pasaron ejecutadas solas y fallaron en la suite completa: son inestables. Buscá una carrera entre una acción y el JS de Moodle (usá esperarJS de los helpers).\nEl estado ARIA puede ser posterior a la limpieza de la prueba; guiate por la línea del error.\n\n${contextoFallos(c.dir, total.resultados)}`;
168	    llamarIA(c, { rol: 'corrector', plantilla: 'corrector', vars: { ...varsImpl, problemas, intento: `regresion-${i}` }, escritura: specDir });
169	    const estaticos = validacionesEstaticas(c, specDir, plan);
170	    if (estaticos.length) return falla(c, 'regresion', 'La corrección de la regresión no pasa las validaciones estáticas.', estaticos.join('\n'));
171	    moodle.desplegar(specDir);
172	    probarSinFuncionalidad(); // las pruebas cambiaron: el resultado anterior ya no vale
173	    moodle.reset();
174	    total = correrPruebas([], c.dir, { crearLineasBaseFaltantes: false });
175	  }
176	  const st = resumen(total.resultados);
177	  c.log('regresion', `Suite completa: ${st.passed} OK, ${st.failed} fallidas, ${st.skipped} omitidas.`, st.failed ? contextoFallos(c.dir, total.resultados) : null);
178	  c.etapa('regresion', st.failed ? 'EJECUTADO' : 'VALIDADO', `${st.passed} OK, ${st.failed} fallidas, ${st.skipped} omitidas.`);
179	  const nuevas = lineasBaseNuevas();
180	  if (nuevas.length) { registrarPendientes(nuevas, specId); c.log('visual', `Líneas base NUEVAS (pantallas que introduce el spec), pendientes de aprobación humana en el PR: ${nuevas.join(', ')}`); }
181	
182	  // 7. Alcance: la IA solo pudo cambiar salidas/<spec>/ y líneas base nuevas; el core de Moodle intacto
183	  const fuera = sh('git status --porcelain').out.split('\n').filter(Boolean).map((l) => l.slice(3))
184	    .filter((f) => !f.startsWith(specDir) && !f.startsWith('corridas/') && !f.startsWith('ia/transcripciones/') && !f.startsWith('visual/') && !f.startsWith('test-results'))
185	    // al reanudar, la fábrica se toma de main (no de la rama): esas diferencias no son obra de la IA
186	    .filter((f) => !(reanudar && sh(`git diff --quiet main -- '${f}'`).code === 0));
187	  const core = moodle.verificarCoreIntacto(rutasPluginsDesplegados());
188	  if (fuera.length || core.length) return falla(c, 'alcance', 'Cambios fuera del alcance permitido.', [...fuera.map((f) => `repo: ${f}`), ...core.map((x) => `core moodle: ${x}`)].join('\n'));
189	  c.log('alcance', 'Solo cambió salidas/ del spec; core de Moodle intacto (git status del árbol de Moodle).');
190	  c.etapa('alcance', 'VALIDADO', 'Solo cambió salidas/ del spec; core de Moodle intacto.');
191	
192	  // 8. Control de verificación honesta (independiente). Bloquea.
193	  const { hallazgos: H, texto: txtH } = auditar({ resultados: total.resultados, sinFeature, plan });
194	  escribir(c.ruta('honestidad.log'), txtH);
195	  c.log('honestidad', H.length ? `BLOQUEADO con ${H.length} hallazgo(s).` : 'OK.', txtH);
196	  if (H.length) return falla(c, 'honestidad', 'El control de verificación honesta bloqueó la corrida. No se abre PR.');
197	  c.etapa('honestidad', 'VALIDADO', 'Sin hallazgos.');
198	  if (st.failed) return falla(c, 'regresion', 'La regresión completa tiene fallos. No se abre PR.');
199	
200	  // 9. Evidencia, trazabilidad, diff, commit, PR (sin merge)
201	  generarTrazabilidad({ plan, specDir, resultados: total.resultados, corrida: c });
202	  shOk(`git add -A ${specDir} visual/lineas-base`);
203	  const diff = sh(`git diff --cached -- ${specDir}/codigo visual/lineas-base`).out;
204	  escribir(`${specDir}/cambios.diff`, diff || '(sin cambios de código: spec de solo pruebas)\n');
205	  shOk(`git add -A ${specDir} ${c.dir} ia/transcripciones visual/lineas-base`);
206	  shOk(`git commit -q -m "feat(${specId}): ${plan.titulo}" -m "Generado por la fábrica. Corrida ${c.dir}."`);
207	  const pr = abrirPR(c, rama, plan, specDir, st, txtH, nuevas);
208	  c.etapa('pr', 'EJECUTADO', `PR propuesto: ${pr}. Pendiente de aprobación humana.`);
209	  c.log('fin', `PR propuesto: ${pr}. El pipeline se detiene en aprobación humana: no mergea ni despliega.`);
210	  sh(`git add -A ${c.dir} && git commit -q -m "chore(${specId}): log final de la corrida" && git push -q origin ${rama}`);
211	  shOk('git checkout -q main');
212	  return 0;
213	}
214	
215	function proponerCambiosVisuales(c, plan, resultados) {
216	  const afectadas = plan.pantallas_afectadas || [];
217	  if (!afectadas.length) return [];
218	  const art = path.join(RAIZ, c.dir, 'artefactos');
219	  if (!fs.existsSync(art)) return [];
220	  const hechas = [];
221	  for (const f of fs.readdirSync(art, { recursive: true }).filter((x) => x.endsWith('-actual.png'))) {
222	    // Playwright nombra el artefacto <nombre-captura>-actual.png; la línea base es <nombre>--<proyecto>.png
223	    const nombre = path.basename(f).replace(/-actual\.png$/, '');
224	    const proyecto = /-movil$/.test(path.dirname(f)) ? 'movil' : 'escritorio';
225	    if (!afectadas.some((p) => nombre.startsWith(p))) continue;
226	    const destino = `visual/lineas-base/${nombre}--${proyecto}.png`;
227	    if (!fs.existsSync(path.join(RAIZ, destino))) continue;
228	    fs.copyFileSync(path.join(art, f), path.join(RAIZ, destino));
229	    hechas.push(destino);
230	  }
231	  if (hechas.length) proponerLineasBase(hechas.map((h) => path.basename(h)), plan.spec_id);
232	  void resultados;
233	  return hechas;
234	}
235	
236	function falla(c, etapa, msg, detalle) {
237	  c.log(etapa, `DETENIDO: ${msg}`, detalle);
238	  c.etapa(etapa === 'reanudar' ? 'precondicion' : etapa, 'FALLIDO', msg);
239	  return 1;
240	}
241	
242	/** Detiene la corrida en BLOQUEADO: deja pregunta.md y el plan en la rama, y vuelve a main sin construir nada. */
243	function bloquear(c, rama, specDir, specPath, bordes) {
244	  const preguntas = bordes.map((b, i) => `## ${i + 1}. ${b.descripcion}\n\n**Pregunta:** ${b.preguntaria}\n\n**Por qué bloquea:** ${b.criterio || '(sin criterio declarado)'}\n`).join('\n');
245	  const md = `# Corrida BLOQUEADA: ${specPath}\n\nLa fábrica no construyó nada: estas decisiones son de producto y no se pueden asumir.\n\n${preguntas}\n`
246	    + `## Cómo continuar\n\nResolver cada punto EN EL SPEC (\`${specPath}\`) y volver a ejecutar:\n\n    node factory/cli.mjs run ${specPath}\n`;
247	  escribir(c.ruta('pregunta.md'), md);
248	  c.etapa('analisis', 'BLOQUEADO', `${bordes.length} ambigüedad(es) bloqueante(s). Ver ${c.ruta('pregunta.md')}.`);
249	  c.log('analisis', `BLOQUEADO: ${bordes.length} ambigüedad(es) bloqueante(s). No se construye nada.`, md);
250	  shOk(`git add -A ${specDir} ${c.dir}`);
251	  shOk(`git commit -q -m "chore(${c.estado.corrida}): corrida bloqueada por ambigüedad" -m "Preguntas en ${c.ruta('pregunta.md')}."`);
252	  const p = sh(`git push -q origin ${rama}`);
253	  if (p.code !== 0) console.error(`Aviso: no se pudo subir la rama ${rama}; queda solo en local.`);
254	  shOk('git checkout -q main');
255	  return 4;
256	}
257	
258	function validarPlan(p, specId) {
259	  const req = ['spec_id', 'titulo', 'naturaleza', 'capa_justificacion', 'criterios', 'bordes'];
260	  for (const k of req) if (p[k] === undefined) throw new Error(`falta "${k}"`);
261	  for (const b of p.bordes) {
262	    if (b.bloqueante !== undefined && typeof b.bloqueante !== 'boolean') throw new Error(`bloqueante debe ser true o false: ${b.descripcion}`);
263	    if (b.bloqueante && !b.preguntaria) throw new Error(`borde bloqueante sin pregunta: ${b.descripcion}`);
264	  }
265	  if (p.spec_id !== specId) throw new Error(`spec_id debe ser "${specId}"`);
266	  if (!Array.isArray(p.criterios) || !p.criterios.length) throw new Error('criterios vacío');
267	  for (const ca of p.criterios) if (!ca.id || !ca.texto || !ca.verificacion) throw new Error(`criterio incompleto: ${JSON.stringify(ca)}`);
268	  if (p.componente && !/^(quizaccess|local|quiz|block|qbank|qtype|qbehaviour|report|tool|theme)_[a-z0-9_]+$/.test(p.componente)) throw new Error(`componente inválido: ${p.componente}`);
269	  if (p.componente && !/^public\//.test(p.ruta_moodle || '')) throw new Error('ruta_moodle debe empezar con public/ (Moodle >= 5.1)');
270	  return p;
271	}
272	
273	function ejecutarSondas(c, sondas) {
274	  const out = [];
275	  for (const s of sondas.slice(0, 8)) {
276	    const body = s.body !== undefined ? `-H 'Content-Type: application/json' --data '${JSON.stringify(s.body).replace(/'/g, "'\\''")}'` : '';
277	    const r = sh(`curl -s -m 15 -X ${s.metodo || 'GET'} ${body} -w '\\n__HTTP__%{http_code}' '${s.url}'`);
278	    const [cuerpo, code] = r.out.split('\n__HTTP__');
279	    out.push({ ...s, respuesta: { http: Number(code), cuerpo: cuerpo.slice(0, 4000) } });
280	    c.log('sonda', `${s.metodo || 'GET'} ${s.url} -> HTTP ${code}`, `${s.descripcion || ''}\n${cuerpo.slice(0, 1500)}`);
281	  }
282	  return out;
283	}
284	
285	function validacionesEstaticas(c, specDir, plan) {
286	  const p = [];
287	  const plugins = moodle.pluginsDe(specDir);
288	  if (plan.componente) {
289	    const esperado = plugins.find((x) => x.componente === plan.componente);
290	    if (!esperado) p.push(`No existe ${specDir}/codigo/${plan.ruta_moodle}/version.php con $plugin->component = '${plan.componente}'.`);
291	    else if (esperado.rel !== plan.ruta_moodle) p.push(`El plugin está en ${esperado.rel} pero el plan dice ${plan.ruta_moodle}.`);
292	  }
293	  p.push(...moodle.lintPHP(specDir).map((x) => `Error de sintaxis PHP: ${x}`));
294	  const pruebas = archivos(`${specDir}/pruebas`, (f) => f.endsWith('.spec.ts'));
295	  if (!pruebas.length) p.push(`No hay pruebas en ${specDir}/pruebas/*.spec.ts`);
296	  const textoPruebas = pruebas.map((f) => leer(f)).join('\n');
297	  p.push(...copiasDeHelpers(archivos(`${specDir}/pruebas`, (f) => f.endsWith('.ts')).map((f) => ({ archivo: f, texto: leer(f) }))));
298	  // El corrector puede resolverlas; si llegaran a la etapa 8 detendrían la corrida sin PR.
299	  p.push(...auditar({}).hallazgos.filter((h) => REGLAS_ESTATICAS.has(h.regla)).map((h) => `[${h.regla}] ${h.donde}: ${h.detalle}`));
300	  for (const ca of plan.criterios) {
301	    if (ca.verificacion === 'proceso') continue;
302	    if (!textoPruebas.includes(`[${ca.id}]`)) p.push(`Ninguna prueba cubre ${ca.id} (el título debe incluir "[${ca.id}]").`);
303	  }
304	  c.log('validacion', p.length ? `${p.length} problema(s) estáticos.` : 'Validaciones estáticas OK (estructura, sintaxis PHP, cobertura de criterios).', p.join('\n') || null);
305	  return p;
306	}
307	
308	function rutasPluginsDesplegados() {
309	  return fs.readdirSync(path.join(RAIZ, 'salidas')).flatMap((s) => moodle.pluginsDe(`salidas/${s}`).map((p) => p.rel));
310	}
311	
312	function abrirPR(c, rama, plan, specDir, st, txtH, nuevas) {
313	  const cuerpo = `## ${plan.titulo}\n\nPropuesto por la fábrica a partir de \`${specDir}/spec.md\`. **El pipeline se detiene aquí: requiere aprobación humana. No mergea ni despliega.**\n\n`
314	    + `### Capa elegida\n\`${plan.componente || 'solo pruebas'}\` (${plan.ruta_moodle || '—'})\n\n${plan.capa_justificacion}\n\n`
315	    + `### Bordes del spec y criterio aplicado\n${plan.bordes.map((b) => `- **${b.descripcion}** → ${b.decision} _(${b.criterio})_`).join('\n')}\n\n`
316	    + `### Evidencia\n- Trazabilidad: \`${specDir}/trazabilidad.md\`\n- Diff: \`${specDir}/cambios.diff\`\n- Corrida: \`${c.dir}/\` (pipeline.log, funcional.xml, visual/, honestidad.log)\n`
317	    + `- Suite completa: ${st.passed} OK, ${st.failed} fallidas, ${st.skipped} omitidas\n\n`
318	    + (nuevas.length ? `### ⚠️ Líneas base visuales NUEVAS — revisar y aprobar\n${nuevas.map((n) => `- \`visual/lineas-base/${n}\``).join('\n')}\nAprobar con: \`node factory/cli.mjs aprobar-linea-base --pendientes --razon "..."\`\n\n` : '')
319	    + `### Control de verificación honesta\n\`\`\`\n${txtH}\`\`\`\n`;
320	  escribir(c.ruta('pr.md'), cuerpo);
321	  const push = sh(`git push -q -u origin ${rama}`);
322	  if (push.code !== 0) { c.log('pr', 'No se pudo hacer push (¿sin remoto/credenciales?). El PR queda descrito en pr.md.', push.err); return `(local) ${c.ruta('pr.md')}`; }
323	  const r = sh(`gh pr create --base main --head ${rama} --title "[${plan.spec_id}] ${plan.titulo}" --body-file ${c.ruta('pr.md')}`);
324	  return r.code === 0 ? r.out.trim() : `(no creado: ${r.err.trim()}) ${c.ruta('pr.md')}`;
325	}
326	
327	// ---------------------------------------------------------------------------------------------------------
328	async function suite() {
329	  const c = corridaActiva = new Corrida('suite');
330	  c.iniciarEstado(ETAPAS_SUITE);
331	  if (!moodle.moodleArriba()) return falla(c, 'precondicion', 'Moodle no responde. Ejecutar: bash entorno/setup.sh');
332	  c.etapa('precondicion', 'VALIDADO', 'Moodle responde.');
333	  for (const s of fs.readdirSync(path.join(RAIZ, 'salidas'))) if (moodle.pluginsDe(`salidas/${s}`).length) {
334	    const d = moodle.desplegar(`salidas/${s}`);
335	    c.log('despliegue', `${s}: ${d.ok ? 'OK' : 'FALLÓ'}`, d.ok ? null : d.salida);
336	  }
337	  moodle.reset();
338	  const r = correrPruebas(resto.filter((a) => !a.startsWith('--')), c.dir);
339	  const s = resumen(r.resultados);
340	  c.log('suite', `Funcional + visual: ${s.passed} OK, ${s.failed} fallidas, ${s.skipped} omitidas. Reporte: ${c.dir}/visual/index.html`, s.failed ? contextoFallos(c.dir, r.resultados) : null);
341	  if (s.failed) copiarDiferencias(c);
342	  c.etapa('pruebas', s.failed ? 'FALLIDO' : 'VALIDADO', `${s.passed} OK, ${s.failed} fallidas, ${s.skipped} omitidas.`);
343	  const { hallazgos: H, texto: txtH } = auditar({ resultados: r.resultados });
344	  escribir(c.ruta('honestidad.log'), txtH);
345	  c.log('honestidad', H.length ? `BLOQUEADO con ${H.length} hallazgo(s).` : 'OK.', txtH);
346	  c.etapa('honestidad', H.length ? 'FALLIDO' : 'VALIDADO', H.length ? `${H.length} hallazgo(s).` : 'Sin hallazgos.');
347	  return s.failed || H.length ? 1 : 0;
348	}
349	
350	/** Copia esperada/obtenida/diferencia de las comparaciones visuales fallidas a visual/diferencias/<corrida>/ */
351	function copiarDiferencias(c) {
352	  const art = path.join(RAIZ, c.dir, 'artefactos');
353	  if (!fs.existsSync(art)) return;
354	  for (const f of fs.readdirSync(art, { recursive: true }).filter((x) => /-(expected|actual|diff)\.png$/.test(x))) {
355	    fs.mkdirSync(path.join(RAIZ, 'visual/diferencias', c.id), { recursive: true });
356	    fs.copyFileSync(path.join(art, f), path.join(RAIZ, 'visual/diferencias', c.id, path.basename(path.dirname(f)) + '--' + path.basename(f)));
357	  }
358	  c.log('visual', `Imágenes esperada/obtenida/diferencia copiadas a visual/diferencias/${c.id}/`);
359	}
360	
361	async function honestidad() {
362	  const cargar = (bandera) => { const p = opt(bandera); return p ? JSON.parse(leer(p)) : undefined; };
363	  const { hallazgos: H, texto } = auditar({ resultados: cargar('--resultados'), sinFeature: cargar('--sin-feature'), plan: cargar('--plan') });
364	  process.stdout.write(texto);
365	  return H.length ? 1 : 0;
366	}
367	
368	async function aprobarLB() {
369	  const razon = opt('--razon');
370	  if (!razon || razon.length < 15) throw new Error('Aprobar una línea base exige --razon "<qué cambió a propósito y por qué>" (mín. 15 caracteres).');
371	  const quien = sh('git config user.name').out.trim() || process.env.USER;
372	  const objetivos = resto.includes('--pendientes') ? null : resto.filter((a) => a.endsWith('.png'));
373	  const hechos = aprobarLineaBase(objetivos, razon, quien);
374	  console.log(hechos.length ? `Aprobadas por ${quien}:\n${hechos.join('\n')}` : 'Nada que aprobar.');
375	  return 0;
376	}
377	
378	async function aprobarPruebas() {
379	  const razon = opt('--razon');
380	  if (!razon || razon.length < 15) throw new Error('Aprobar el manifiesto de pruebas exige --razon (mín. 15 caracteres).');
381	  // Importación dinámica a propósito: nada de la copia de trabajo de factory/honestidad/ se carga al auditar.
382	  const { construirManifiesto } = await import('./honestidad/verificar.mjs');
383	  const m = construirManifiesto();
384	  escribir('factory/honestidad/manifiesto.json', JSON.stringify(m, null, 2) + '\n');
385	  fs.appendFileSync(path.join(RAIZ, 'factory/honestidad/aprobaciones.log'), `${new Date().toISOString()} ${sh('git config user.name').out.trim()}: ${Object.keys(m.pruebas).length} pruebas — ${razon}\n`);
386	  console.log(`Manifiesto actualizado (${Object.keys(m.pruebas).length} pruebas). Se vuelve referencia cuando se mergea a main.`);
387	  return 0;
388	}
