1	// Análisis estático de archivos de prueba Playwright, SIN IA y sin depender del generador.
2	// Extrae, por prueba: título, línea, cantidad de asserts, matchers usados, omisiones, opciones de captura.
3	// Es deliberadamente simple (léxico + balanceo de llaves) para que un humano pueda auditarlo línea por línea.
4	
5	export const MATCHERS_DEBILES = new Set([
6	  'toBeTruthy', 'toBeFalsy', 'toBeDefined', 'toBeUndefined', 'toBeNull', 'toBeNaN', 'toBeAttached',
7	  'toBeGreaterThanOrEqual', 'toBeLessThanOrEqual', 'toBeInstanceOf', 'anything', 'any',
8	]);
9	
10	/** Quita comentarios y contenido de strings (conserva longitudes para mapear líneas). */
11	function enmascarar(src) {
12	  let out = '';
13	  let i = 0;
14	  while (i < src.length) {
15	    const c = src[i], n = src[i + 1];
16	    if (c === '/' && n === '/') { while (i < src.length && src[i] !== '\n') { out += ' '; i++; } continue; }
17	    if (c === '/' && n === '*') { while (i < src.length && !(src[i] === '*' && src[i + 1] === '/')) { out += src[i] === '\n' ? '\n' : ' '; i++; } out += '  '; i += 2; continue; }
18	    if (c === '"' || c === "'" || c === '`') {
19	      const q = c; out += q; i++;
20	      while (i < src.length && src[i] !== q) { if (src[i] === '\\') { out += '  '; i += 2; continue; } out += src[i] === '\n' ? '\n' : '_'; i++; }
21	      out += q; i++; continue;
22	    }
23	    out += c; i++;
24	  }
25	  return out;
26	}
27	
28	const linea = (src, idx) => src.slice(0, idx).split('\n').length;
29	
30	function cierre(m, desde) {
31	  // desde = índice de '(' ; devuelve índice del ')' que lo cierra
32	  let prof = 0;
33	  for (let i = desde; i < m.length; i++) {
34	    if (m[i] === '(' || m[i] === '{' || m[i] === '[') prof++;
35	    else if (m[i] === ')' || m[i] === '}' || m[i] === ']') { prof--; if (prof === 0) return i; }
36	  }
37	  return m.length - 1;
38	}
39	
40	export function analizarArchivo(archivo, src) {
41	  const m = enmascarar(src);
42	  const pruebas = [];
43	  const re = /\b(test|it)(\.(only|skip|fixme|fail))?\s*\(\s*(['"`])/g;
44	  let x;
45	  while ((x = re.exec(m))) {
46	    const inicio = x.index;
47	    const parAbre = m.indexOf('(', inicio);
48	    const parCierra = cierre(m, parAbre);
49	    const q = x[4];
50	    const tIni = m.indexOf(q, parAbre) + 1;
51	    const tFin = m.indexOf(q, tIni);
52	    const titulo = src.slice(tIni, tFin);
53	    const cuerpoM = m.slice(parAbre, parCierra + 1);
54	    const cuerpo = src.slice(parAbre, parCierra + 1);
55	    const matchers = [...cuerpoM.matchAll(/\.\s*(not\s*\.\s*)?(to[A-Z]\w*)\s*\(/g)].map((y) => (y[1] ? 'not.' : '') + y[2]);
56	    pruebas.push({
57	      archivo, titulo, linea: linea(src, inicio),
58	      modificador: x[3] || null,
59	      asserts: (cuerpoM.match(/\bexpect\s*(\.\s*soft\s*)?\(/g) || []).length,
60	      soft: (cuerpoM.match(/\bexpect\s*\.\s*soft\s*\(/g) || []).length,
61	      matchers: matchers.sort(),
62	      fuertes: matchers.filter((k) => !MATCHERS_DEBILES.has(k.replace(/^not\./, ''))).length,
63	      capturas: (cuerpoM.match(/toHaveScreenshot\s*\(/g) || []).length,
64	      opcionesCaptura: [...cuerpo.matchAll(/(maxDiffPixels|maxDiffPixelRatio|threshold)\s*:\s*([\d.]+)/g)].map((y) => `${y[1]}=${y[2]}`),
65	      mascaras: (cuerpoM.match(/\bmask\s*:/g) || []).length,
66	      triviales: [...cuerpo.matchAll(/expect\s*\(\s*(true|false|null|undefined|\d+|'[^']*'|"[^"]*")\s*\)/g)].map((y) => y[0]),
67	      // Aserciones web-first (asíncronas) sin await: la promesa queda flotando y la prueba nunca falla por ellas.
68	      sinAwait: [...cuerpoM.matchAll(/(await\s+)?expect\s*\([^;]*?\)\s*(\.\s*not)?\s*\.\s*(to(Have|BeVisible|BeHidden|BeEnabled|BeDisabled|BeChecked|BeEditable|BeEmpty|BeFocused|BeInViewport|BeAttached|ContainText|Pass)\w*)\s*\(/g)]
69	        .filter((y) => !y[1]).map((y) => y[3]),
70	      tragaErrores: /\.catch\s*\(\s*\(\s*\w*\s*\)\s*=>\s*(\{\s*\}|undefined|null|true|false)\s*\)|catch\s*(\(\s*\w*\s*\))?\s*\{\s*\}/.test(cuerpo),
71	      mockRed: /\b(route\.fulfill|page\.route|context\.route|routeFromHAR)\b/.test(cuerpoM),
72	      tags: [...titulo.matchAll(/(@[\w-]+|\[(CA-\d+|HUMO|REG-[\w-]+)\])/g)].map((y) => y[1]),
73	    });
74	  }
75	  // skip/fixme/only dinámicos o a nivel describe (dentro o fuera de pruebas)
76	  const omisiones = [...m.matchAll(/\b(test|describe|it)(\.describe)?\.(skip|fixme|only)\s*\(/g)].map((y) => ({ tipo: y[3], linea: linea(src, y.index), texto: src.slice(y.index, src.indexOf('\n', y.index)).trim() }));
77	  return { archivo, pruebas, omisiones };
78	}
79	
80	export const idPrueba = (p) => `${p.archivo}::${p.titulo}`;
81

